// pl — Polski (polonês).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// TRATAMENTO: **ty**, e não *Pan/Pani*. É o que o CLAUDE.md manda, e no polonês não custa nada a
// mais: é o registro de todo app de conversa no país. O "ty" vai em minúscula — a maiúscula (Ty,
// Twój) é de carta pessoal, e numa interface soa como cartão de felicitação.
//
// ONDE O POLONÊS ESCONDE O GÊNERO — e esta é a decisão que importa neste arquivo:
//
// No PRESENTE, o "ty" é neutro (masz, możesz, piszesz). O sexo de quem lê aparece em três lugares:
//
//   1. no PASSADO: zapomniałeś (homem) / zapomniałaś (mulher) — "esqueceu a senha?";
//   2. no CONDICIONAL: chciałbyś / chciałabyś — "você gostaria";
//   3. em ADJETIVO E PARTICÍPIO depois de "ser": jesteś pewien/pewna, wyciszony/wyciszona,
//      zalogowany/zalogowana — "tem certeza", "você está silenciado", "continua conectado".
//
// A saída é reescrever a frase para não passar por nenhum dos três, e quase sempre há uma forma
// natural: "Nie pamiętasz hasła?" (presente) em vez de "zapomniałeś"; "Masz wyciszony mikrofon"
// (o adjetivo vai para o MICROFONE, que é masculino de verdade) em vez de "jesteś wyciszony";
// "Na pewno…?" em vez de "czy jesteś pewien"; "Masz zaproszenie" em vez de "zostałeś zaproszony".
// O futuro dos verbos perfectivos (stracisz, dostaniesz) é neutro e pode ser usado à vontade; o
// futuro composto (będziesz musiał) NÃO é.
//
// Os NOMES DE CARGO (Administrador, Dono, Membro) ficam no masculino genérico, como em toda
// interface polonesa — são rótulos de papel, não frases dirigidas a quem lê. Onde a frase fala com
// a pessoa sobre o cargo dela, ela vira "Masz rolę właściciela", que não diz o sexo de ninguém.
//
// ---------------------------------------------------------------------------------------------------
// PLURAL: o polonês tem TRÊS formas (1 wiadomość, 2–4 wiadomości, 5+ wiadomości — e 22 volta a ser
// "wiadomości" mas 12 não), e o t() do Syden não escolhe forma. A saída é a mesma do russo: rótulo
// e número, "wiadomości: {n}", que é gramatical para qualquer n. "dni" serve para 2–4 e para 5+,
// então "{dias} dni" pode ficar direto.
//
// DECLINAÇÃO: o polonês declina NOME PRÓPRIO (Ania → do Ani, z Anią). Um {nome} solto depois de
// preposição sai no caso errado em metade das vezes. Por isso o nome nunca vem colado à preposição:
// vem depois de um substantivo que leva o caso ("w społeczności {comunidade}", "na kanale {nome}")
// ou depois de dois-pontos ("Napisz do: {nome}"), que é a convenção das interfaces polonesas.
//
// ALGARISMOS, medidos e não supostos: `Intl.NumberFormat('pl').format(1234567)` devolve
// `1 234 567` (espaço fino como separador) e o número grande sai como "45 mln". São os latinos; os
// números deste arquivo vão com 0-9.
//
// ASPAS: as polonesas são „assim”, baixa na abertura e alta no fechamento.
//
// VOCABULÁRIO, decidido uma vez: comunidade = społeczność, canal = kanał, sala de voz = pokój
// głosowy, chamada = połączenie (głosowe), conversa = rozmowa, mensagem = wiadomość, senha = hasło,
// lixeira = kosz, tópico = wątek, usuário = użytkownik, conta = konto, dono = właściciel,
// cargo = rola, convite = zaproszenie, pedido de amizade = zaproszenie do znajomych, amigos =
// znajomi, avatar = awatar, perfil = profil, transmissão = transmisja, recado = nagranie,
// soundboard = panel dźwięków, vila = wioska, guarda-roupa = garderoba, denúncia = zgłoszenie,
// tela = ekran.
//
// SELO E INSÍGNIA SEPARADOS, como nas outras línguas: selo = pieczęć (o da comunidade),
// insígnia = odznaka (a da pessoa).
//
// As FONTES do nome são adjetivos femininos porque concordam com "czcionka" (Zaokrąglona,
// Szeryfowa, Odręczna…), e as cores dos cosméticos são substantivos (Szmaragd, Rubin, Miedź).

