  'Descrição': 'Opis',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'Po wyłączeniu transmisja osób w pokoju pojawia się jako zaproszenie i zaczyna się pobierać dopiero, gdy klikniesz Oglądaj. Oszczędza to internet i procesor — zwłaszcza w pełnym pokoju.',
