    'Podczas połączenia ten przycisk odtwarza te dźwięki wszystkim w pokoju. Zainstaluj gotowe paczki albo prześlij własne; ulubione są na początku panelu.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'To pierwsza rzecz, którą ktoś widzi po wejściu do społeczności, tylko raz. Bez tego trafia prosto na listę kanałów.',
  'É assim que os outros veem você na lista e nas conversas.': 'Tak widzą cię inni na liście i w rozmowach.',
  'é o que você está enviando': 'to wysyłasz',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'To twój jedyny sposób logowania. Ustaw hasło przed odłączeniem.',
