  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Gdy wiadomość zbierze dość gwiazdek ⭐, Syden publikuje ją na kanale wyróżnień. Gwiazdka od osoby, która ją napisała, się nie liczy, a usunięcie wiadomości usuwa też wyróżnienie.',
