  'Mês': 'Miesiąc',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'W dniu urodzin osoby, która podała datę, Syden publikuje życzenia na wybranym kanale. Zamiast imienia użyj {pessoa}.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Tylko dzień i miesiąc, nigdy rok. Społeczności, które ogłaszają urodziny, składają życzenia tego dnia. To opcjonalne i można to usunąć w każdej chwili.',
