  'Anjo': 'Anioł',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'W nocy wybierz osobę, którą chcesz chronić. Jeśli wilkołaki ją zaatakują, przeżyje.',
  'Da vila': 'Z wioski',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'W nocy śpij. W dzień odkryj, kto jest wilkołakiem, i głosuj, żeby wyrzucić wilkołaki z gry.',
