  'Você já usou a sua visão esta noite.': 'Twoja wizja na tę noc jest już wykorzystana.',
  'Clique em alguém para descobrir se é lobisomem.': 'Kliknij osobę, żeby sprawdzić, czy jest wilkołakiem.',
