  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}): treść usunięta z Sydena, bo {quem} twierdzi, że ma do niej prawa. Jeśli masz zgodę na publikację, odpowiedz tutaj i wyjaśnij: twoja odpowiedź zostanie wzięta pod uwagę. Dopóki sprawa się nie wyjaśni, treść pozostaje niedostępna. Regulamin wyjaśnia, jak to działa, w sekcji 4: https://syden.chat/termos.html#direito-autoral',
