  'Derrapar': 'Drift',
  'Uma corrida de kart. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, com itens e a Copa da Cenoura.': 'Wyścig gokartów. Solo — na czas i z duchami znajomych; z ekipą — na żywo, z przedmiotami i Pucharem Marchewki.',
  'Pomar': 'Sad',
  'Copa da Cenoura': 'Puchar Marchewki',
  'contra {nomes}': 'przeciw {nomes}',
  'Usar o item': 'Użyj przedmiotu',
  'Olhar para trás': 'Spójrz do tyłu',
  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'Strzałki do kierowania, spacja do driftu, E, by użyć przedmiotu.',
  'Copa da turma': 'Puchar ekipy',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'Puchary Marchewki, które ekipa przejechała do końca, w Wyścigu królików.',
  'Bosque': 'Las',
  'Cânion': 'Kanion',
  'Copa do Repolho': 'Puchar Kapusty',
  'Festa dos coelhos': 'Królicza impreza',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Pięć rund szybkich gier, każdy na swoim ekranie: refleks, celność, pamięć i spostrzegawczość. Kto jest najlepszy w danej rundzie, dostaje więcej punktów.',
  'Saque rápido': 'Szybki strzał',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Czekaj na sygnał i naciśnij jak najszybciej. Przed sygnałem odpadasz.',
  'Medidor de força': 'Siłomierz',
  'Pare a barra o mais perto possível de 100%.': 'Zatrzymaj pasek jak najbliżej 100%.',
  'Parar o relógio': 'Zatrzymaj zegar',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Zatrzymaj zegar dokładnie na 10 sekundach. Liczby znikają po 3.',
  'Jogo dos copos': 'Gra w kubki',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Zobacz, gdzie jest marchewka, i śledź kubek. Szybsze trafienie jest warte więcej.',
  'Siga o coelho': 'Podążaj za królikiem',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Powtórz strzałki w kolejności. Po każdym trafieniu dochodzi kolejna.',
  'Tiro ao alvo': 'Strzelanie do celu',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'Trafiaj w cele, które się pojawią. Każdy jest wart punkt.',
  'Cedo demais!': 'Za wcześnie!',
  'Não valeu': 'Nie liczy się',
