  'No telhado': 'Na dachu',
  'O abajur': 'Lampka',
  'O balcão': 'Lada',
  'O barco desliza: tire o pé antes da curva. As argolas laranja dão um empurrão.': 'Łódka się ślizga: puść gaz przed zakrętem. Pomarańczowe pierścienie dają kopa.',
  'O chefe da turma': 'Wielki szef',
  'O coelho do recado': 'Królik od wiadomości',
  'O fliperama': 'Automat do gier',
  'O fone': 'Słuchawki',
  'O que a estante de troféus do quarto mostra?': 'Co pokazuje półka z trofeami w pokoju?',
  'O que a minhoca faz pela horta?': 'Co dżdżownica robi dla ogródka?',
  'O que dá para fazer com os móveis do seu quarto?': 'Co można zrobić z meblami w swoim pokoju?',
  'O que nasce de uma semente?': 'Co wyrasta z nasionka?',
  'O que o mascote do Syden veste?': 'Co nosi maskotka Sydena?',
  'O que um espantalho espanta?': 'Co straszy strach na wróble?',
  'O tapete': 'Dywan',
  'O vaso': 'Wazon',
  'Oito': 'Osiem',
  'Onda no açude': 'Fale w stawie',
  'Os livros': 'Książki',
  'Os pássaros': 'Ptaki',
  'Os pódios dos jogos': 'Podia gier',
  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Słuchaj, powtórz uderzenia w tym samym rytmie i dodaj jedno na końcu.',
  'Paiol': 'Spichlerz',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Zatrzymaj każdy pasek z portretem na miejscu, od góry do dołu.',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Zatrzymaj trzy bębny na tej samej figurze. Każda trójka to punkt.',
  'Pedras': 'Kamienie',
  'Pegue a galinha': 'Złap kurę',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Zbieraj marchewki na lodzie i uciekaj przed kapustami.',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Weź złotą marchewkę i zanieś ją do bramy. Jednej brakuje: popchnij tego, kto ją niesie!',
  'Pilotar (para trás, freia e dá ré)': 'Sterowanie (do tyłu hamuje i cofa)',
  'Plantar': 'Posadzić je',
  'Ponte do riacho': 'Most na strumieniu',
  'Praga na toca': 'Szkodniki w norze',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'Ustal celowanie, potem siłę. Wygrywa ten, kto zatrzyma się najbliżej dołka.',
  'Preta': 'Czarny',
  'Pronta': 'Gotowa',
  'Pula o ponteiro': 'Przeskocz wskazówkę',
  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'Skocz z huśtawki na liść. Najdalszy jest wart więcej.',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Skacz, gdy wskazówka przechodzi. Jest coraz szybsza.',
  'Pulo do balanço': 'Skok z huśtawki',
  'Qual destes bichos é uma praga da horta?': 'Które z tych stworzeń jest szkodnikiem w ogródku?',
  'Qual destes cresce debaixo da terra?': 'Co z tego rośnie pod ziemią?',
  'Qual destes é o mais pesado?': 'Co z tego jest najcięższe?',
  'Qual destes é uma ferramenta da horta?': 'Co z tego jest narzędziem ogrodowym?',
  'Qual destes é uma fruta vermelha?': 'Co z tego jest czerwonym owocem?',
  'Quantas orelhas tem um coelho?': 'Ile uszu ma królik?',
  'Quantas patas tem um coelho?': 'Ile łap ma królik?',
  'Quantas patas tem um inseto?': 'Ile nóg ma owad?',
  'Quantas patas tem uma aranha?': 'Ile nóg ma pająk?',
  'Quantas rodadas tem uma partida da Festa dos coelhos?': 'Ile rund ma partia Króliczej imprezy?',
  'Quatro': 'Cztery',
  'Que bicho é o mascote do Syden?': 'Jakim zwierzęciem jest maskotka Sydena?',
  'Quem ajuda as flores a virar frutos?': 'Kto pomaga kwiatom zmienić się w owoce?',
  'Quem está atrás da turma?': 'Kto jest za tłumem?',
  'Quem está em qual toca?': 'Kto jest w której norze?',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'Kto ma wiosło, ten puszcza fale; ci na tratwie skaczą w porę!',
  'Quem fica atrás do balcão do salão?': 'Kto stoi za ladą w sali?',
  'Quiz relâmpago': 'Błyskawiczny quiz',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'Odbij, gdy rzodkiewka dotrze do bazy. Idealnie w porę leci dalej.',
  'Rebater o rabanete': 'Odbij rzodkiewkę',
