  'Regar a horta': 'Podlej ogródek',
  'Regata da toca': 'Regaty w norze',
  'Reme alternando ◀ e ▶ quando o remo estiver com você.': 'Wiosłuj na zmianę ◀ i ▶, gdy masz wiosło.',
  'Repolhos no gelo': 'Kapusty na lodzie',
  'Retrato do coelho': 'Portret królika',
  'Revezamento do riacho': 'Sztafeta na strumieniu',
