  'Roda da feira': 'Diabelski młyn',
  'Sal e areia': 'Sól i piasek',
  'Segure e solte: cenoura teleguiada': 'Przytrzymaj i puść: kierowana marchewka',
  'Seis': 'Sześć',
  'Sem vidas: agora é torcer pela turma.': 'Koniec żyć: teraz zostaje kibicowanie ekipie.',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Śledź zwierzaki od nory do nory. Na końcu wskaż, gdzie jest ten z balonem.',
  'Silo': 'Silos',
  'Solte o cipó quando ele estiver na faixa clara.': 'Puść lianę, gdy jest w jasnym pasku.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Puść, gdy rzepa celuje w pole. Im szybciej się kręci, tym dalej leci.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Wespnij się do wiatrowskazu. Upadki i wrony cofają na ostatnie piętro.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Wspinaj się po stodole po deskach, belach siana i ruchomych belkach aż do wiatrowskazu na szczycie, unikając spadających narzędzi i wron. W Solo przeciw zegarowi i duchom znajomych.',
  'Subida inválida.': 'Nieprawidłowa wspinaczka.',
  'Subir contra': 'Wspinaj się przeciw',
