  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'Zbieraj skrzynki i przebijaj balony innych. Kto zostanie bez balonów, odpada.',
  'Você venceu!': 'Zwycięstwo!',
