  '{n} voltas': 'Okrążenia: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Energia to życie i turbo: uderzanie w krawędź ją zużywa, różowy pas ją ładuje.',
  'A nave explodiu: a energia acabou.': 'Statek wybuchł: skończyła się energia.',
  'Posição: {posicao} de {total}': 'Pozycja: {posicao} z {total}',
  'Escolher a pista': 'Wybierz trasę',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Wyścig statków-marchewek na podwieszonej trasie, dużo szybszy niż kart. Energia to życie i turbo: uderzanie w krawędź ją zużywa, różowy pas ją ładuje, a wypadnięcie z trasy to upadek. W trybie Solo: na czas i przeciwko duchom znajomych.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Karty na zamkniętej arenie, każdy z trzema balonami. Zbieraj skrzynki i używaj przedmiotów, by przebijać balony innych: kto zostanie bez balonów, odpada, a wygrywa ten, kto przetrwa.',
  'Esquadrilha da toca': 'Eskadra z nory',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Marchewkowe samolociki przeciw szkodnikom w ogródku: unikaj nasion, zbieraj wsparcie i na końcu zestrzel mechanicznego stracha na wróble. Ekipa leci przez te same fale, a punkty eskadry się sumują.',
  'O espantalho caiu!': 'Strach na wróble spadł!',
  'A praga venceu desta vez.': 'Tym razem wygrały szkodniki.',
