  'Desvie das sementes e derrube a praga. O espantalho vem no fim.': 'Unikaj nasion i zestrzeliwuj szkodniki. Strach na wróble pojawi się na końcu.',
  'Sem vidas: agora é torcer pela esquadrilha.': 'Brak żyć: teraz kibicuj eskadrze.',
