  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Wybierz statek i dotknij morza. Przeciągnij, by go przesunąć.',
  'Sortear a frota': 'Losuj flotę',
  'Sua frota já está pronta.': 'Twoja flota jest już gotowa.',
  'Ponha todos os navios antes.': 'Najpierw ustaw wszystkie statki.',
  'Escolha um navio.': 'Wybierz statek.',
