  'Os navios não podem encostar um no outro.': 'Statki nie mogą się stykać.',
  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Osiem dołków w 3D, z rampami, zamkiem i wiatrakiem, wszyscy grają ten sam w tym samym czasie. Przeciągnij, by wycelować i nadać siłę, i puść. Wygrywa ten, kto ma w sumie najmniej uderzeń.',
  'Ver o buraco de cima': 'Zobacz dołek z góry',
  'Fora da pista! Mais uma tacada.': 'Poza torem! Jedno uderzenie więcej.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Przeciągnij w bok, by celować, i w dół, by nadać siłę, i puść. Na klawiaturze: strzałki celują, a przytrzymana spacja daje siłę.',
  'Futebol dos coelhos': 'Królicza piłka nożna',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Piłka nożna na małym boisku, widziana z góry. Dotknij piłki, by ją prowadzić, przytrzymaj spację, by strzelić mocniej, i podaj klawiszem X. W pokoju drużyny uzupełniają roboty.',
  'Quantos por time?': 'Ilu na drużynę?',
  'Seu time venceu!': 'Twoja drużyna wygrała!',
  'Seu time perdeu.': 'Twoja drużyna przegrała.',
  'Passe': 'Podanie',
  'Chutar': 'Strzał',
  'Chutar (segure para mais força)': 'Strzał (przytrzymaj, by mocniej)',
  'Gol!': 'Gol!',
  'Gol contra': 'Gol samobójczy',
  'Partida inválida.': 'Nieprawidłowa partia.',
  'Ninguém para jogar.': 'Nie ma z kim grać.',
  'Caça às pragas da horta': 'Polowanie na szkodniki w ogródku',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Wrony i koniki polne atakują ogródek. Celuj i klikaj, żeby je trafić, zanim uciekną: amunicja jest policzona, a każda fala nadchodzi szybciej. Wygrywa ten, kto zdobędzie najwięcej punktów.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Celuj i klikaj w szkodniki, zanim uciekną. Każdy strzał kosztuje jedną marchewkę.',
