  'Bater': 'Uderz',
  'Neste buraco': 'Na tym dołku',
  'Total': 'Razem',
  'Tacadas: {n}': 'Uderzenia: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Pociągnij piłkę do tyłu i puść. Na klawiaturze: strzałki celują, a przytrzymana spacja daje siłę.',
  'Na água! Mais uma tacada.': 'W wodzie! Jedno uderzenie więcej.',
  'No buraco!': 'W dołku!',
  'Acabaram as tacadas.': 'Uderzenia się skończyły.',
  'Para a esquerda': 'W lewo',
  'Para a direita': 'W prawo',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Strzałki do biegania, spacja do skoku (przytrzymaj, żeby skoczyć wyżej).',
  'Nenhum amigo jogou esta fase ainda.': 'Nikt ze znajomych jeszcze nie grał na tym poziomie.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Deszcz w ogródku: każdy dostaje {n} marchewek.',
  '{nome} achou {n} cenouras escondidas.': '{nome} znajduje {n} ukrytych marchewek.',
  '{nome} trocou de lugar com {outro}.': '{nome} zamienia się miejscami z {outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Za mało osób: rozgrywka skończyła się przed czasem, bez trofeów.',
  'Saiu antes do fim': 'Wyjście przed końcem',
  'Jogar o dado': 'Rzuć kostką',
  '{nome} comprou a cenoura dourada!': '{nome} kupuje złotą marchewkę!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Kupić złotą marchewkę za {preco} marchewek?',
  'Comprar': 'Kup',
  '{nome} chegou à cenoura dourada.': '{nome} dociera do złotej marchewki.',
  'Quantas rodadas?': 'Ile rund?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Króliki bronią ogródka przed lisami, wronami i borsukiem. Idźcie razem, bijcie kombosami i pilnujcie się nawzajem: od 1 do 4 osób.',
  'Pulo do coelho': 'Skok królika',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Wyścig platformowy: biegnij, skacz i nie spadnij. Solo — na czas i z duchami znajomych; z ekipą — na żywo, na jednym poziomie albo na wszystkich trzech.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Zamieniaj dwa sąsiednie warzywa, żeby zebrać trzy lub więcej takich samych. Stos rośnie bez przerwy: nie pozwól mu sięgnąć góry. Z ekipą łańcuchy i kombosy wysyłają skrzynki pozostałym.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Sześć dołków minigolfa, wszyscy grają ten sam w tym samym czasie. Pociągnij piłkę do tyłu i puść, żeby uderzyć. Wygrywa ten, kto ma w sumie najmniej uderzeń.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Każdy w swojej turze rzuca kostką i idzie przez ogródek. Zbieraj marchewki, żeby kupić złotą marchewkę, a po każdej rundzie ekipa gra w minigrę. Wygrywa ten, kto ma najwięcej złotych marchewek.',
  'Os pódios e as conquistas da turma': 'Podia i osiągnięcia ekipy',
