  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Chodź po stolicach Brazylii, kupuj miasta i pobieraj czynsz od tych, którzy na nich staną. Z całym regionem możesz stawiać budynki. Wymieniaj się, licytuj na aukcjach i nie zostań bez pieniędzy.',
