  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Klasyczne domino dla 2–4 osób (przy 4 w parach). Dokładaj kostki do końców, a kto pierwszy wyłoży ostatnią, zgarnia punkty z rąk pozostałych.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco z São Paulo, z odkrytą kartą i atutami, we dwoje lub w dwóch parach. Zgłoś truco, podbij do sześciu, dziewięciu i dwunastu albo uciekaj. Wygrywa, kto zdobędzie 12 punktów.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Warcaby brazylijskie: bicie jest obowiązkowe, do przodu i do tyłu, a damka chodzi po całej przekątnej. Pokój ogląda.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Każdy ukrywa swoją flotę i strzela w morze drugiego. Po trafieniu strzelasz jeszcze raz. Wygrywa, kto pierwszy zatopi całą flotę. Pokój ogląda.',
