  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Weź składniki ze skrzynek, posiekaj je na desce, ugotuj na kuchence i w piekarniku tak, żeby się nie przypaliły, ułóż na talerzu i wydaj w okienku. Wszyscy dostają te same zamówienia: wygrywa ten, kto w 3 minuty wyda najwięcej talerzy.',
  'Pegar ou largar': 'Weź lub odłóż',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Ta gra potrzebuje grafiki 3D, która nie otworzyła się na tym urządzeniu.',
  'Este prato não é o pedido.': 'Ten talerz to nie zamówienie.',
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'Króliczy przejazd',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': 'Jedna minuta w skateparku. Skacz, kręć się, grinduj po poręczach i łącz triki w combo: każdy kolejny trik mnoży punkty, ale upadek zabiera całe combo.',
  Pausar: 'Pauza',
  'Caiu!': 'Upadek!',
  'Melhor combo: {n}': 'Najlepsze combo: {n}',
  'Trânsito da toca': 'Ruch przy norze',
  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'Minuta, żeby przepuszczać auta przez skrzyżowanie tak, by się nie zderzyły. Pełna kolejka też kosztuje punkty.',
  Liberar: 'Puść',
  'Carrinhos da toca': 'Samochodziki z nory',
  'Uma pista de carrinhos de brinquedo com quatro faixas: o carro segue a faixa sozinho, e você só acelera. Acelerou demais na curva, ele sai voando e perde tempo. No Solo, contra o relógio, os fantasmas dos amigos e robôs.': 'Tor dla samochodzików-zabawek z czterema pasami: auto samo trzyma się swojego pasa, a ty tylko przyspieszasz. Za mocno w zakręcie i wylatuje z toru, tracąc czas. Solo — na czas, z duchami znajomych i robotami.',
  'Acelerar': 'Przyspiesz',
  'Saiu da pista!': 'Poza torem!',
  'Saídas da pista: {n}': 'Wypadnięcia z toru: {n}',
  'Segure para acelerar e solte antes da curva: quando o carro treme, ele está no limite.': 'Przytrzymaj, by przyspieszyć, i puść przed zakrętem: gdy auto drży, jest na granicy.',
