  // a Ponte da toca (06/11/2026)
  'Ponte da toca': 'Most przy norze',
  'Trinta segundos para montar uma ponte de madeira e aço. Ganha quem levar o tráfego até o outro lado gastando menos.': 'Trzydzieści sekund na most z drewna i stali. Wygrywa ten, kto przeprowadzi ruch na drugą stronę najtaniej.',
  'Pista': 'Jezdnia',
  'Aço': 'Stal',
  'Testar': 'Test',
  'Montar': 'Budowa',
  'Passou!': 'Udało się!',
  '{n}% do caminho': '{n}% drogi',
  'Gincana da toca': 'Tor przeszkód z nory',
  'Uma corrida de obstáculos em 3D: corra, pule e se equilibre por plataformas, esteiras, serras e varredores até a bandeira. Caiu, volta à última bandeira. No Solo, contra o relógio e os fantasmas dos amigos.': 'Tor przeszkód w 3D: biegnij, skacz i utrzymuj równowagę na platformach, taśmach, wśród pił i obrotowych ramion aż do flagi. Upadek oznacza powrót do ostatniej flagi. W solo przeciw zegarowi i duchom znajomych.',
  'Quedas: {n}': 'Upadki: {n}',
  'Tocar o sino: todos os trabalhadores para dentro do centro da vila': 'Uderz w dzwon: wszyscy robotnicy do środka centrum wioski',
  'Tocar o sino de novo: todos de volta ao trabalho': 'Uderz w dzwon jeszcze raz: wszyscy z powrotem do pracy',
  'Este lugar já está cheio.': 'To miejsce jest już pełne.',
  'Clássico': 'Klasyczny',
  'Colorido': 'Kolorowy',
  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Diagnostyka hosta",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Ograniczone logi Dockera, SSH, logind i jądra z trzech ostatnich uruchomień. Mogą zawierać adresy IP.",
  "Atualizar diagnóstico": "Odśwież diagnostykę",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Nie ma jeszcze migawki. Zostanie zebrana przy następnym otwarciu sejfu.",
  "Coletado em {data}": "Zebrano {data}",
  "Medido pela {nome}": "Zmierzone przez {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Te same liczby co w panelu dostawcy. Obejmuje dysk, którego serwer sam nie mierzy.",
  "Ações no servidor": "Działania na serwerze",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Historia w Hetzner: włączanie, wyłączanie i ponowne uruchamianie, z panelu lub przez API. Awaria bez działania tutaj nie została wywołana tymi drogami.",
  "Nenhuma ação registrada.": "Brak zarejestrowanych działań.",
  "Ligar o servidor": "Włącz serwer",
  "Desligar o servidor": "Wyłącz serwer",
  "Reiniciar o servidor": "Uruchom serwer ponownie",
