  'Seu palpite está salvo. Dá para mudar até fechar.': "Twój typ jest zapisany. Możesz go zmienić do zamknięcia.",
  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Tło kamery",
  'Desfocado': "Rozmyj",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Rozmywa, usuwa lub zastępuje to, co widać za tobą. Obraz z kamery nie opuszcza do tego twojego komputera.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Natywna",
  'Resolução': "Rozdzielczość",
  'Quadros por segundo': "Klatki na sekundę",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Na wypadek, gdy automatyczny wybór się pomyli: rozdzielczość i klatki zostają takie, jakie wybierzesz, od początku do końca transmisji.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Efekty głosu i kamery robione na twoim komputerze, bez wysyłania czegokolwiek na serwer.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Loch w norze",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Przejdźcie razem przez norę króla grzybów: komnaty pełne stworków, skrzynia z marchewką, która leci i wraca, przyciski, które wymagają dwóch osób naraz, i zamknięte drzwi. Od 1 do 4 osób.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ring przy norze",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Boks na refleks przeciw trzem rywalom z komputera. Czytaj zapowiedź każdego ciosu, unikaj lub blokuj i bij w lukę. Cios, gdy rękawica błyśnie, napełnia gwiazdę mocnego ciosu.",
  'Esquivar': "Unik",
  'Abaixar e defender': "Schyl się i blokuj",
  'Socar': "Uderz",
  'Soco forte': "Mocny cios",
  'Aperte os socos para levantar!': "Wciskaj ciosy, żeby wstać!",
  'Lutas vencidas: {n}': "Wygrane walki: {n}",
  'Nocaute!': "Nokaut!",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Marchewkowy Komandos",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Biegnij i strzelaj z ekipą: marchewkomiotacz celuje w ośmiu kierunkach, granat otwiera drogę, a kto uwolni zamknięte w klatkach króliczki, dostaje wzmocnienie. Na końcu czeka smok: od 1 do 4 osób.",
  'Andar e mirar': "Ruch i celowanie",
  'Granada': "Granat",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Gwiezdna Trasa",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Króliki w statkach kosmicznych nad powierzchnią planety i w kosmosie: strzelaj, przytrzymaj strzał, żeby namierzyć cel, rób beczkę, żeby odbijać pociski, i wybierz drogę na rozwidleniu. Ekipa leci tą samą trasą, a na końcu czeka boss.",
  'Pirueta': "Beczka",
  'Segure para travar a mira': "Przytrzymaj, by namierzyć",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Pinball w ogródku",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Stół do pinballa w ogródku warzywnym: trzymaj sprężynę, odbijaj się od kapust i przewróć trzy marchewki, żeby zapaliła się nora królika, która wypuszcza jeszcze jedną kulkę. Trzy kulki, a zbyt mocne potrząsanie blokuje stół.",
  'Palhetas': "Łapki",
  'Mola': "Sprężyna",
  'Sacudir': "Potrząśnij",
  'Bola salva!': "Kulka uratowana!",
  'Multibola!': "Multikulka!",
  'Mesa travada!': "Stół zablokowany!",
  'Cuidado!': "Uwaga!",
  'Recordes dos amigos': "Rekordy znajomych",
  // O Planador da toca (16/11/2026)
  'Planador da toca': 'Szybowiec z nory',
  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Wyzwania lotnicze: lotnia, plecak odrzutowy i spadochron. Przeleć przez obręcze i wyląduj na celu, blisko środka i delikatnie.',
  'Asa-delta': 'Lotnia',
