  'Desafio desconhecido.': 'Nieznane wyzwanie.',
  'O voo está andando.': 'Lot trwa.',
  'O voo não está andando.': 'Lot nie trwa.',
  'Você não está neste voo.': 'Nie bierzesz udziału w tym locie.',
  'Quem começou escolhe o desafio.': 'Kto zaczął, ten wybiera wyzwanie.',
  // Lendas da Toca (16/11/2026)
