  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Ta sama pozycja po raz trzeci to remis, podobnie 20 ruchów samymi damkami bez bicia.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "W nocy zobacz, kogo zaatakowały wilkołaki. Jedna mikstura ratuje tę osobę, a druga wyrzuca kogoś z gry; każdej można użyć raz.",
