  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Miasto, którego nikt nie kupi, idzie na licytację. Zastawienie miasta daje pieniądze, ale wtedy nie pobiera ono czynszu.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Podpowiedź podświetla bierkę, która ma się ruszyć. Zadanie z podpowiedzią nie daje punktów; w wyścigu zabiera 10 sekund.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Atut to wartość następna po wartości odkrytej karty i bije wszystkie. Między nimi: karo, pik, kier i trefl, czyli zap.",
  "A última nave de cada volta sai.": "Ostatni statek w każdym okrążeniu odpada.",
  "Abaixar": "Schyl się",
  "Acertos em sequência: {n}": "Trafienia z rzędu: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Idź o tyle pól, ile wyrzuci kostka, i kup stolicę, na której staniesz. Kto stanie w mieście kogoś innego, płaci czynsz.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Każdy wiersz, kolumna i blok 3 × 3 ma liczby od 1 do 9, bez powtórzeń.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Każda osoba dostaje 3 karty. Rękę bierze, kto wygra 2 z 3 rund.",
  "Campeonato": "Mistrzostwa",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Przy 11 punktach para widzi karty i decyduje, czy grać rękę jedenastu. Wygrywa, kto dojdzie do 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Z całym regionem buduj do 4 budynków: czynsz rośnie z każdym.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Z gwiazdami mocny cios (★) zużywa je wszystkie naraz i boli bardziej.",
  "Dica": "Podpowiedź",
  "Dica: este problema não pontua": "Podpowiedź: to zadanie nie daje punktów",
  "Dica: tira 10 segundos": "Podpowiedź: zabiera 10 sekund",
  "Eliminação": "Eliminacja",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Dostaw kostkę z tą samą liczbą do jednego z końców na stole.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Wybierz pole, a potem liczbę. Ołówek notuje tylko dla ciebie.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Zrób unik i uderz zaraz potem: to kontratak, i daje gwiazdę.",
  "Fora da corrida na volta {n}.": "Odpadnięcie z wyścigu na okrążeniu {n}.",
  "Força das cartas": "Siła kart",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Wygrywa największy majątek na koniec rund albo osoba, która zostanie.",
  "Iniciante": "Początkujący",
  "Mestre": "Mistrz",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "W Serii każde trafienie daje trudniejsze zadanie, a pierwszy błąd ją kończy.",
  "O número pequeno no botão diz quantos ainda faltam.": "Mała liczba na przycisku mówi, ile jeszcze brakuje.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Pięć tras z rzędu przeciw komputerowi, na punkty.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Zgłoś truco, a ręka jest warta 3. Odpowiadająca strona przyjmuje, ucieka albo podbija do 6, 9 lub 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Kto wyłoży ostatnią kostkę, zgarnia punkty z rąk pozostałych. Gdy gra się zablokuje, punkty bierze, kto ma najmniej punktów w ręce.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Bez pasującej kostki dobierz. Gdy nie ma czego dobrać, kolej przechodzi dalej.",
  "Sequência": "Seria",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Uderz, gdy rękawica błyśnie: cios się zatrzymuje, a ty zyskujesz gwiazdę.",
