  "Chuva de estrelas": "Deszcz gwiazd",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Z biciem: otoczenie dwóch kamieni rywala między dwoma twoimi zdejmuje oba; pięć bić też wygrywa.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Z ograniczeniem 3-3 czarne nie mogą zrobić dwóch otwartych trójek naraz.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "Ze specjalnymi zamknięciami zamknięcie dubletem albo kamieniem pasującym na oba końce liczy się podwójnie; dublet na oba końce poczwórnie.",
