  "No meio": "Środek",
  "No mineiro não há vira: as manilhas são o 4 de paus, o 7 de copas, o ás de espadas e o 7 de ouros.": "W mineiro nie ma odkrytej karty: atuty to czwórka trefl, siódemka kier, as pik i siódemka karo.",
  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "W mineiro ręka jest warta 2, a truco, sześć, dziewięć i dwanaście są warte 4, 8, 10 i 12. Przy 10 punktach jest ręka dziesięciu: grać o 4 albo uciec i oddać 2.",
