  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Losuje się tajne zwierzę, a każdy zgaduje inne. Każda próba pokazuje, co pasuje do tajnego: gromada, dieta, gdzie żyje i waga. Kto trafi w mniejszej liczbie prób, dostaje więcej punktów.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Losuje się tajnego dinozaura, a każdy zgaduje innego. Każda próba pokazuje, co pasuje do tajnego: okres, dieta, grupa, długość i gdzie go znaleziono. Kto trafi w mniejszej liczbie prób, dostaje więcej punktów.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Losuje się tajny pierwiastek chemiczny, a każdy zgaduje inny. Każda próba pokazuje, co pasuje do tajnego: rodzina, stan skupienia, okres, grupa i liczba atomowa. Kto trafi w mniejszej liczbie prób, dostaje więcej punktów.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Losuje się tajny stan Brazylii, a każdy zgaduje inny. Każda próba pokazuje odległość i kierunek do tajnego, region, ludność, powierzchnię, wybrzeże i granicę z innym krajem. Kto trafi w mniejszej liczbie prób, dostaje więcej punktów.",
